from __future__ import annotations

import html
import json
import re

from .design_director import palette_for, validate_design_spec
from .motion import inline_motion_bundle
from .seo_generator import locality_from_address, public_site_url, seo_text


def esc(value: object) -> str:
    return html.escape(str(value or ""), quote=True)


def _review_stars(value: object) -> str:
    try:
        score = max(0.0, min(5.0, float(value)))
    except (TypeError, ValueError):
        score = 0.0
    stars = []
    for index in range(5):
        fill = max(0.0, min(1.0, score - index))
        stars.append(
            f'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#d5d9d7" d="m12 2 3.09 6.26 6.91 1-5 4.87 1.18 6.88L12 17.77l-6.18 3.24L7 14.13 2 9.26l6.91-1L12 2Z"/><path fill="#d99b2b" fill-opacity="{fill:.2f}" d="m12 2 3.09 6.26 6.91 1-5 4.87 1.18 6.88L12 17.77l-6.18 3.24L7 14.13 2 9.26l6.91-1L12 2Z"/></svg>'
        )
    return f'<span class="review-stars" role="img" aria-label="{score:g} de 5 estrellas">{"".join(stars)}</span>'


def render_html(data: dict, spec: dict) -> str:
    validate_design_spec(spec)
    direction, layout = spec["art_direction"], spec["layout"]
    palette = palette_for(direction)
    name = esc(data.get("name") or "Negocio local")
    category = esc(data.get("category") or spec["industry"])
    address = esc(data.get("address"))
    phone = data.get("phone_original", data.get("phone", ""))
    phone_href = data.get("phone_e164", "")
    wa = data.get("whatsapp_url", "")
    maps = data.get("source_url", "")
    rating = esc(data.get("rating"))
    count = esc(data.get("review_count"))
    reviews = data.get("reviews", [])
    photos = list(data.get("photos", []))[:8]
    if data.get("photo_sources") and any(not str(p).startswith(("http://", "https://")) for p in photos):
        photos = data["photos"]
    # Keep an authentic business photo in the first viewport when available.
    if photos and layout == "centered":
        layout = "split"
    address_parts = [item.strip() for item in str(data.get("address", "")).split(",") if item.strip()]
    if address_parts and address_parts[-1].casefold() in {"argentina", "united states", "usa", "españa", "spain"}:
        address_parts.pop()
    location_label = data.get("city") or locality_from_address(data.get("address", ""))
    art_label = "<br>".join(filter(None, (category, esc(location_label))))
    motif = _brand_motif(direction)
    image_context = " · ".join(filter(None, (data.get("category", ""), location_label)))
    hero_alt = f"{data.get('name', 'Negocio local')}{': ' + image_context if image_context else ''} · fotografía del negocio"
    hero_img = f'<button class="photo-trigger hero-photo-trigger" type="button" data-photo-open aria-label="Ampliar fotografía de {name}"><img class="hero-photo" data-flip-id="business-photo-0" src="{esc(photos[0])}" alt="{esc(hero_alt)}" width="1600" height="1200" fetchpriority="high" decoding="async"></button>' if photos else f'<div class="hero-art" role="img" aria-label="Ilustración conceptual de {name}, no es una fotografía del local"><span class="orb orb-a"></span><span class="orb orb-b"></span><span class="art-word">{art_label}</span><span class="art-caption">ILUSTRACIÓN · NO ES FOTO DEL LOCAL</span></div>'
    gallery = ''.join(f'<button class="photo-trigger" type="button" data-photo-open aria-label="Ampliar fotografía {index + 2} de {name}"><img loading="lazy" decoding="async" width="1600" height="1200" data-flip-id="business-photo-{index + 1}" src="{esc(photo)}" alt="{esc(data.get("name", "Negocio local"))}{": " + image_context if image_context else ""} · foto {index + 2}"></button>' for index, photo in enumerate(photos[1:]))
    trust = []
    if rating:
        trust.append(f'<div><strong>★ {rating}</strong><span>Calificación en Google</span></div>')
    if count:
        trust.append(f'<div><strong>{count}</strong><span>Reseñas en Google</span></div>')
    if category:
        trust.append(f'<div><strong>{category}</strong><span>Rubro</span></div>')
    if address:
        trust.append(f'<div><strong>{address}</strong><span>Ubicación</span></div>')
    trust_html = ''.join(trust)
    service_cards = ''.join(f'<details class="service-card"><summary><span class="service-index">{i:02d}</span><span class="service-title">{esc(item["title"])}</span><span class="service-toggle" aria-hidden="true">+</span></summary><p>{esc(item["description"])}</p></details>' for i, item in enumerate(spec.get("services", []), 1))
    service_section = f'<section class="section services reveal" id="servicios"><div class="section-head"><span class="eyebrow">PROPUESTA</span><h2>Servicios</h2></div><div class="service-grid">{service_cards}</div></section>' if service_cards and "services" in spec.get("sections", []) else ''
    review_cards = ''.join(f'<article class="review-card">{_review_stars(item["rating"])}<blockquote>“{esc(item["text"])}”</blockquote><p>{esc(item["author"])}{(" · " + esc(item["date"])) if item.get("date") else ""}</p></article>' for item in reviews)
    if review_cards:
        if len(reviews) >= 3:
            review_layout = f'<div class="review-carousel" data-review-carousel><button class="carousel-arrow review-prev" type="button" aria-label="Opinión anterior">←</button><div class="review-viewport" tabindex="0" aria-label="Opiniones de clientes"><div class="review-track">{review_cards}</div></div><button class="carousel-arrow review-next" type="button" aria-label="Opinión siguiente">→</button></div>'
        else:
            review_layout = f'<div class="review-grid">{review_cards}</div>'
        reviews_section = f'<section class="section reviews reveal" id="opiniones"><div class="section-head"><span class="eyebrow">REPUTACIÓN</span><h2>Lo que comparten nuestros clientes</h2></div>{review_layout}<a class="text-link" href="{esc(maps)}" target="_blank" rel="noopener">Ver opiniones originales en Google Maps ↗</a></section>'
    elif rating or count:
        reviews_section = f'<section class="section rating-panel reveal"><span class="eyebrow">EN GOOGLE MAPS</span><h2>{"★ " + rating if rating else ""}{(" · " + count + " reseñas") if count else ""}</h2><a class="text-link" href="{esc(maps)}" target="_blank" rel="noopener">Consultar opiniones originales ↗</a></section>'
    else:
        reviews_section = ''
    # Verified listing reviews are factual content, so the AI section plan cannot suppress them.
    if phone_href:
        phone_line = f'<a href="tel:{esc(phone_href)}">{esc(phone)}</a>'
    else:
        phone_line = ''
    web = data.get("website", "")
    details = ''.join([f'<p>{address}</p>' if address else '', f'<p>{phone_line}</p>' if phone_line else '', f'<p><a href="{esc(web)}" target="_blank" rel="noopener">Visitar sitio web ↗</a></p>' if web else '', f'<p><a href="{esc(maps)}" target="_blank" rel="noopener">Abrir ficha y ubicación ↗</a></p>' if maps else ''])
    if data.get("hours_visible"):
        hours_text = " · ".join(str(item) for item in data["hours_visible"][:7]) if isinstance(data["hours_visible"], list) else str(data["hours_visible"])
        details += f'<p><span>Horario visible en Google Maps:</span> {esc(hours_text)}</p>'
    wa_btn = f'<a class="btn btn-primary" href="{esc(wa)}" target="_blank" rel="noopener">{esc(spec["hero"].get("primary_cta") or "Consultar por WhatsApp")} <span>↗</span></a>' if wa else ''
    map_link = f'<a class="btn btn-outline" href="{esc(maps)}" target="_blank" rel="noopener">Ver en Google Maps</a>' if maps else ''
    gallery_count = max(0, len(photos) - 1)
    photo_treatment = spec.get("photo_treatment", "editorial_crop")
    gallery_section = f'<section class="section gallery reveal"><div class="section-head"><span class="eyebrow">GALERÍA</span><h2>Fotos de {name}</h2></div><div class="gallery-grid gallery-count-{gallery_count} gallery-treatment-{photo_treatment}">{gallery}</div></section>' if gallery else ''
    viewer_arrows = '<button class="viewer-arrow viewer-prev" type="button" aria-label="Foto anterior">←</button><button class="viewer-arrow viewer-next" type="button" aria-label="Foto siguiente">→</button>' if len(photos) > 1 else ''
    viewer = f'<dialog class="photo-viewer" id="photo-viewer" aria-label="Fotos de {name}"><button class="viewer-close" type="button" aria-label="Cerrar foto" autofocus>×</button>{viewer_arrows}<figure class="viewer-figure"><img class="viewer-image" alt=""><figcaption class="viewer-caption"></figcaption></figure><span class="viewer-count" aria-live="polite"></span></dialog>' if photos else ''
    intro_text = esc(spec["introduction"].get("text", ""))
    intro_section = f'<section class="section intro reveal" id="el-negocio"><div><span class="eyebrow">{category}</span><h2>{esc(spec["introduction"]["title"])}</h2></div><p>{intro_text}</p></section>' if "introduction" in spec.get("sections", []) else ""
    location_map_link = f'<a class="text-link" href="{esc(maps)}" target="_blank" rel="noopener">Abrir ubicación ↗</a>' if maps else ''
    location_section = (f'<section class="section location reveal" id="ubicacion"><div class="location-copy"><span class="eyebrow">CÓMO ENCONTRARLO</span><h2>En {esc(location_label or "tu zona")}</h2><p>{address}</p><div class="actions">{map_link}{wa_btn}</div></div><div class="location-card"><span class="location-mark">⌖</span><div><strong>{name}</strong><p>{address}</p>{phone_line}</div>{location_map_link}</div></section>' if address or maps else '')
    directions = maps
    public_url = public_site_url(data.get("public_url", ""))
    absolute_photo_urls = [f"{public_url}/{photo.lstrip('/')}" for photo in photos if public_url and not str(photo).startswith(("http://", "https://"))]
    absolute_photo_urls.extend(str(photo) for photo in photos if str(photo).startswith(("https://", "http://")))
    schema_description = str(spec["hero"].get("description") or data.get("description") or "").strip()
    json_ld = {"@context": "https://schema.org", "@type": "LocalBusiness", "name": html.unescape(name)}
    if public_url: json_ld["@id"] = public_url + "#business"
    if schema_description: json_ld["description"] = schema_description
    if address:
        address_parts = [item.strip() for item in str(data.get("address", "")).split(",") if item.strip()]
        country = address_parts.pop() if address_parts and address_parts[-1].casefold() in {"argentina", "united states", "usa", "españa", "spain"} else ""
        street = next((part for part in address_parts if re.search(r"\d", part) and not re.match(r"^[A-Z]?\d{4,5}$", part, flags=re.I)), html.unescape(address))
        postal = {"@type": "PostalAddress", "streetAddress": street}
        if location_label: postal["addressLocality"] = str(location_label)
        if len(address_parts) > 1: postal["addressRegion"] = address_parts[-1]
        postal_match = re.search(r"\b([A-Z]\d{4}(?:[A-Z]{3})?|\d{4,5})\b", str(data.get("address", "")), flags=re.I)
        if postal_match: postal["postalCode"] = postal_match.group(1)
        if country or data.get("country"): postal["addressCountry"] = country or str(data["country"])
        json_ld["address"] = postal
    if phone_href: json_ld["telephone"] = phone_href
    if public_url: json_ld["url"] = public_url
    if maps: json_ld["hasMap"] = maps
    if absolute_photo_urls: json_ld["image"] = absolute_photo_urls[:8]
    coordinates = data.get("coordinates")
    if isinstance(coordinates, dict) and isinstance(coordinates.get("latitude"), (int, float)) and isinstance(coordinates.get("longitude"), (int, float)):
        if -90 <= coordinates["latitude"] <= 90 and -180 <= coordinates["longitude"] <= 180:
            json_ld["geo"] = {"@type": "GeoCoordinates", "latitude": coordinates["latitude"], "longitude": coordinates["longitude"]}
    # Independent composition, art direction and photo geometry create meaningful visual variants.
    visual_effects = spec.get("visual_effects", [])
    css = _css(palette) + _art_direction_css(direction) + _premium_layout_css() + _premium_gallery_css(gallery_count, photo_treatment) + _effect_css(visual_effects)
    seo = seo_text(data.get("name", ""), data.get("category", ""), data.get("address", ""))
    title, description = esc(seo["title"]), esc(seo["description"])
    canonical = f'<link rel="canonical" href="{esc(public_url)}">' if public_url else ''
    og_url = f'<meta property="og:url" content="{esc(public_url)}">' if public_url else ''
    og_image = f'<meta property="og:image" content="{esc(absolute_photo_urls[0])}"><meta name="twitter:image" content="{esc(absolute_photo_urls[0])}"><meta name="twitter:card" content="summary_large_image">' if absolute_photo_urls else '<meta name="twitter:card" content="summary">'
    robots = "index,follow,max-image-preview:large" if public_url else "noindex,nofollow"
    json_ld_text = json.dumps(json_ld, ensure_ascii=False).replace("</", "<\\/")
    direction = re.sub(r"[^a-z_]+", "", direction)
    layout = re.sub(r"[^a-z]+", "", layout)
    motion_markup = inline_motion_bundle()
    content_blocks = {"trust": f'<section class="trust reveal">{trust_html}</section>' if trust_html else "", "introduction": intro_section, "services": service_section, "gallery": gallery_section, "reviews": reviews_section, "location": location_section}
    requested_order = [key for key in spec.get("sections", []) if key in content_blocks and content_blocks[key]]
    for essential in ("introduction", "services", "gallery", "reviews", "location"):
        if content_blocks[essential] and essential not in requested_order:
            requested_order.append(essential)
    sections_html = "".join(content_blocks[key] for key in requested_order)
    effect_tokens = " ".join(visual_effects)
    return f'''<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="{robots}"><title>{title}</title><meta name="description" content="{description}">{canonical}<meta property="og:locale" content="es_AR"><meta property="og:site_name" content="{name}"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="website">{og_url}{og_image}<meta name="theme-color" content="{palette['background']}"><script type="application/ld+json">{json_ld_text}</script><style>{css}</style></head><body class="art-{direction} layout-{layout}" data-effects="{esc(effect_tokens)}"><div class="scroll-progress" aria-hidden="true"></div><header class="nav"><a class="brand" href="#inicio">{name}<small>{category}</small></a><nav><a href="#el-negocio">El negocio</a>{'<a href="#servicios">Servicios</a>' if service_cards else ''}{'<a href="#opiniones">Opiniones</a>' if reviews else ''}<a href="#ubicacion">Ubicación</a><a href="#contacto">Contacto</a>{wa_btn}</nav><button class="menu" aria-label="Abrir menú" aria-expanded="false">☰</button></header><main id="inicio"><section class="hero"><div class="hero-copy"><span class="eyebrow">{esc(spec['hero']['eyebrow'])}</span><h1 data-motion-heading>{esc(spec['hero']['headline'])}</h1><p>{esc(spec['hero']['description'])}</p><div class="actions">{wa_btn}{map_link}</div>{f'<div class="hero-rating">★ {rating} <span>({count} reseñas)</span></div>' if rating else ''}</div><div class="hero-media">{hero_img}{motif}</div></section>{sections_html}<section class="section contact reveal" id="contacto"><div><span class="eyebrow">CONTACTO</span><h2>{esc(spec['contact']['title'])}</h2><p>{esc(spec['contact']['text'])}</p><div class="contact-details">{details}</div></div><div class="contact-actions">{wa_btn}{map_link}</div></section></main>{viewer}<footer><span>{name}</span><span>Vista previa · datos por revisar antes de publicar</span></footer>{f'<a class="wa-float" href="{esc(wa)}" target="_blank" rel="noopener" aria-label="Abrir WhatsApp">{_wa_svg()}</a>' if wa else ''}<script>const b=document.querySelector('.menu');b?.addEventListener('click',()=>{{const n=document.querySelector('.nav nav');const o=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!o));n.classList.toggle('open',!o)}});document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{{const t=document.querySelector(a.getAttribute('href'));if(t){{e.preventDefault();t.scrollIntoView({{behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}})}}}}));if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){{const io=new IntersectionObserver(entries=>entries.forEach(e=>{{if(e.isIntersecting){{e.target.classList.add('is-visible');io.unobserve(e.target)}}}}),{{threshold:.12}});document.querySelectorAll('.reveal').forEach(el=>io.observe(el))}}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('is-visible'));</script>{motion_markup}</body></html>'''


def _effect_css(effects: list[str]) -> str:
    """Original, lightweight CSS treatments selected by the design director."""
    rules = []
    if "glass_surfaces" in effects:
        rules.append("body[data-effects*='glass_surfaces'] .trust>div,body[data-effects*='glass_surfaces'] .location-card,body[data-effects*='glass_surfaces'] .hero-rating{background:color-mix(in srgb,var(--surface) 76%,transparent);backdrop-filter:blur(16px) saturate(1.2);-webkit-backdrop-filter:blur(16px) saturate(1.2);border:1px solid color-mix(in srgb,var(--ink) 12%,transparent);border-radius:18px;box-shadow:0 20px 55px color-mix(in srgb,var(--ink) 9%,transparent)}body[data-effects*='glass_surfaces'] .trust{border:0;gap:10px}body[data-effects*='glass_surfaces'] .trust>div{padding:16px 20px}")
    if "ambient_orbits" in effects:
        rules.append("body[data-effects*='ambient_orbits'] .hero-media{position:relative}body[data-effects*='ambient_orbits'] .hero-media:before,body[data-effects*='ambient_orbits'] .hero-media:after{content:'';position:absolute;z-index:1;pointer-events:none;border-radius:50%;border:1px solid color-mix(in srgb,var(--accent) 62%,transparent);width:clamp(130px,19vw,230px);aspect-ratio:1;right:-5%;top:4%;box-shadow:0 0 70px color-mix(in srgb,var(--accent) 22%,transparent),inset 0 0 42px color-mix(in srgb,var(--accent) 8%,transparent);animation:orbit-drift 9s ease-in-out infinite alternate}body[data-effects*='ambient_orbits'] .hero-media:after{width:clamp(70px,11vw,138px);right:10%;top:auto;bottom:-7%;border-style:dashed;opacity:.68;animation-duration:13s;animation-direction:alternate-reverse}@keyframes orbit-drift{to{transform:translate(-18px,22px) rotate(24deg) scale(1.08)}}@media(max-width:760px){body[data-effects*='ambient_orbits'] .hero-media:before{right:0}body[data-effects*='ambient_orbits'] .hero-media:after{right:4%}}@media(prefers-reduced-motion:reduce){body[data-effects*='ambient_orbits'] .hero-media:before,body[data-effects*='ambient_orbits'] .hero-media:after{animation:none}}")
    if "editorial_reveal" in effects:
        rules.append("body[data-effects*='editorial_reveal'] .hero-line-clip,body[data-effects*='editorial_reveal'] .section-head{overflow:hidden}body[data-effects*='editorial_reveal'] .hero-line-clip{padding-bottom:.12em;margin-bottom:-.12em}body[data-effects*='editorial_reveal'] .hero-photo{will-change:clip-path,transform}body[data-effects*='editorial_reveal'] .section-head h2{text-wrap:balance}")
    if "kinetic_gallery" in effects:
        rules.append("body[data-effects*='kinetic_gallery'] .gallery-grid .photo-trigger{transform:translateY(var(--gallery-offset,0));transition:transform .7s cubic-bezier(.2,.75,.25,1),box-shadow .45s}body[data-effects*='kinetic_gallery'] .gallery-grid .photo-trigger:nth-child(even){--gallery-offset:18px}body[data-effects*='kinetic_gallery'] .gallery-grid .photo-trigger:hover{--gallery-offset:0}")
    if "photo_depth" in effects:
        rules.append("body[data-effects*='photo_depth'] .hero-photo-trigger{perspective:1100px;transform-style:preserve-3d}body[data-effects*='photo_depth'] .hero-photo{transform-style:preserve-3d;will-change:transform,filter;transition:filter .35s,box-shadow .45s}body[data-effects*='photo_depth'] .hero-photo-trigger:hover .hero-photo{filter:saturate(1.08) contrast(1.02);box-shadow:0 34px 86px color-mix(in srgb,var(--ink) 25%,transparent)}@media(hover:none){body[data-effects*='photo_depth'] .hero-photo{will-change:auto}}@media(prefers-reduced-motion:reduce){body[data-effects*='photo_depth'] .hero-photo{will-change:auto}}")
    return "".join(rules)


def _premium_gallery_css(count: int, treatment: str = "editorial_crop") -> str:
    shared = ".gallery-grid{align-items:stretch}.gallery-grid .photo-trigger{min-width:0;overflow:hidden;border-radius:var(--photo-radius,14px);background:var(--surface);box-shadow:0 18px 50px #15231c12;transition:transform .45s cubic-bezier(.2,.75,.25,1),box-shadow .45s}.gallery-grid .photo-trigger:hover{transform:translateY(-5px);box-shadow:0 28px 70px #15231c24}.gallery-grid .photo-trigger img{width:100%;height:100%;min-height:240px;object-fit:cover;transition:transform .75s cubic-bezier(.2,.75,.25,1)}.gallery-grid .photo-trigger:hover img{transform:scale(1.045)}.gallery .section-head{display:grid;grid-template-columns:1fr auto;align-items:end;max-width:none;border-bottom:1px solid var(--line);padding-bottom:20px}.gallery .section-head .eyebrow{grid-column:1/-1}.gallery .section-head h2{max-width:15ch;margin-bottom:0}.gallery-grid.gallery-count-1{grid-template-columns:minmax(0,1fr)}.gallery-grid.gallery-count-1 img{height:clamp(260px,40vw,520px)}.gallery-grid.gallery-count-2{grid-template-columns:1.35fr 1fr}.gallery-grid.gallery-count-2 img{height:clamp(240px,31vw,420px)}.gallery-grid.gallery-count-3{grid-template-columns:1.25fr .85fr;grid-template-rows:repeat(2,minmax(180px,260px))}.gallery-grid.gallery-count-3 .photo-trigger:first-child{grid-row:span 2}.gallery-grid.gallery-count-3 img{height:100%;min-height:100%}.gallery-grid.gallery-count-4,.gallery-grid.gallery-count-5,.gallery-grid.gallery-count-6,.gallery-grid.gallery-count-7{grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:clamp(160px,18vw,250px)}.gallery-grid.gallery-count-4 .photo-trigger:first-child,.gallery-grid.gallery-count-5 .photo-trigger:first-child,.gallery-grid.gallery-count-6 .photo-trigger:first-child,.gallery-grid.gallery-count-7 .photo-trigger:first-child{grid-column:span 2;grid-row:span 2}.gallery-grid.gallery-count-4 .photo-trigger:nth-child(2),.gallery-grid.gallery-count-5 .photo-trigger:nth-child(2),.gallery-grid.gallery-count-6 .photo-trigger:nth-child(2),.gallery-grid.gallery-count-7 .photo-trigger:nth-child(2){grid-column:span 2}.review-stars{display:inline-flex;gap:2px;align-items:center;margin:0 0 4px}.review-stars svg{display:block;width:18px;height:18px;flex:none}.hero-photo{content-visibility:auto}.section{content-visibility:auto;contain-intrinsic-size:auto 640px}.hero{content-visibility:visible}"
    mobile = "@media(max-width:760px){.gallery .section-head{display:block}.gallery-grid.gallery-count-2,.gallery-grid.gallery-count-3{grid-template-columns:1fr 1fr;grid-template-rows:auto}.gallery-grid.gallery-count-2 .photo-trigger:first-child,.gallery-grid.gallery-count-3 .photo-trigger:first-child{grid-row:auto;grid-column:span 2}.gallery-grid.gallery-count-2 img,.gallery-grid.gallery-count-3 img{height:190px;min-height:190px}.gallery-grid.gallery-count-4,.gallery-grid.gallery-count-5,.gallery-grid.gallery-count-6,.gallery-grid.gallery-count-7{grid-template-columns:1fr 1fr;grid-auto-rows:170px}.gallery-grid.gallery-count-4 .photo-trigger:first-child,.gallery-grid.gallery-count-5 .photo-trigger:first-child,.gallery-grid.gallery-count-6 .photo-trigger:first-child,.gallery-grid.gallery-count-7 .photo-trigger:first-child{grid-column:span 2;grid-row:span 2}}@media(prefers-reduced-motion:reduce){.gallery-grid .photo-trigger,.gallery-grid .photo-trigger img{transition:none}.gallery-grid .photo-trigger:hover,.gallery-grid .photo-trigger:hover img{transform:none}}"
    treatments = {
        "editorial_crop": ".gallery-treatment-editorial_crop .photo-trigger:first-child{transform:translateY(-12px)}.gallery-treatment-editorial_crop .photo-trigger:last-child{transform:translateY(12px)}",
        "bento_mosaic": ".gallery-treatment-bento_mosaic{gap:10px}.gallery-treatment-bento_mosaic .photo-trigger{border-radius:4px}.gallery-treatment-bento_mosaic .photo-trigger:nth-child(even){transform:translateY(18px)}",
        "film_strip": ".gallery-treatment-film_strip{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;overscroll-behavior-inline:contain;padding:8px 3px 18px}.gallery-treatment-film_strip .photo-trigger{flex:0 0 min(56vw,680px);height:clamp(250px,42vw,540px);scroll-snap-align:center}.gallery-treatment-film_strip .photo-trigger img{height:100%}",
        "minimal_grid": ".gallery-treatment-minimal_grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.gallery-treatment-minimal_grid .photo-trigger{border-radius:2px;box-shadow:none}.gallery-treatment-minimal_grid .photo-trigger img{height:clamp(220px,28vw,360px)}",
    }
    selected = treatments.get(treatment, treatments["editorial_crop"])
    if treatment == "film_strip":
        mobile += "@media(max-width:760px){.gallery-treatment-film_strip .photo-trigger{flex-basis:84%;height:250px}}"
    if treatment == "editorial_crop":
        mobile += "@media(max-width:760px){.gallery-treatment-editorial_crop .photo-trigger:first-child,.gallery-treatment-editorial_crop .photo-trigger:last-child{transform:none}}"
    return shared + selected + mobile


